 static Store RichStore(){var s=NewStore();for(int i=0;i<3;i++){var id=new Guid(40+i,0,0,new byte[8]);var data=new byte[]{50,(byte)i,55};s.Rs[0].Blobs.Add(Tuple.Create("TitleBlob"+i,id,data));File.WriteAllBytes(Path.Combine(s.Folder(0),id.ToString("N").ToUpperInvariant()),data);}s.Rs[0].Total=9;File.WriteAllBytes(Path.Combine(s.Folder(0),"container.1"),Meta(s.Rs[0]));s.WriteIndex();return s;}
 static Dictionary<string,byte[]> ZipData(string path){using(var fs=File.OpenRead(path))using(var z=new ZipArchive(fs,ZipArchiveMode.Read)){return z.Entries.ToDictionary(e=>e.FullName,e=>{using(var m=new MemoryStream())using(var r=e.Open()){r.CopyTo(m);return m.ToArray();}},StringComparer.Ordinal);}}
 static string Rewrite(string source,string name,Action<Dictionary<string,byte[]>> change){var data=ZipData(source);change(data);string path=Path.Combine(root,name+".zip");using(var fs=new FileStream(path,FileMode.CreateNew))using(var z=new ZipArchive(fs,ZipArchiveMode.Create)){foreach(var x in data){var e=z.CreateEntry(x.Key);using(var stream=e.Open())stream.Write(x.Value,0,x.Value.Length);}}return path;}
 static Dictionary<string,object> Json(byte[] raw){return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(raw));}
 static byte[] JsonBytes(object m){return new UTF8Encoding(false).GetBytes(new JavaScriptSerializer().Serialize(m));}
 static void BackupCore(){
  var s=RichStore();var snapshot=ProfileStore.Scan(s.Wgs);var selected=snapshot.Profiles.Single(p=>p.DisplayName=="0");string before=Fingerprint(s.Wgs);string backups=Path.Combine(root,"b");var verified=ProfileBackup.Create(snapshot,selected,backups);Check("selected Create returns verified identity",verified.ProfileId==selected.StableId&&verified.ContextToken==selected.ContextToken&&verified.Files.Length==3&&verified.RawIndexRecordSha256==snapshot.Containers.Single(c=>c.LogicalContainerName==selected.LogicalContainerName).RecordSha256);Check("backup leaves entire nine-blob store unchanged",Fingerprint(s.Wgs)==before&&snapshot.Containers.Sum(c=>c.Blobs.Length)==9);var reopened=ProfileBackup.Verify(verified.FilePath);Check("reopen ZIP verification identity",reopened.Sha256==verified.Sha256&&reopened.Files.All(f=>verified.Files.Any(x=>x.PhysicalFileName==f.PhysicalFileName&&x.Bytes==f.Bytes&&x.Sha256==f.Sha256)));
  var zip=ZipData(verified.FilePath);Check("exact five archive members",zip.Keys.OrderBy(x=>x).SequenceEqual(new[]{"blobs/000.bin","blobs/001.bin","manifest.json","metadata.bin","selected-profile.xml"}));var xml=new XmlDocument();xml.XmlResolver=null;xml.LoadXml(Encoding.UTF8.GetString(zip["selected-profile.xml"]));var containers=xml.SelectNodes("/XbConnectedStorageSpace/Data/Containers/Container");var node=containers[0];Check("XML exactly selected container and CDATA",containers.Count==1&&node.Attributes["name"].Value==selected.LogicalContainerName&&node.SelectNodes("Blobs/Blob").Count==2&&node.SelectNodes("Blobs/Blob").Cast<XmlNode>().All(n=>n.ChildNodes.Count==1&&n.FirstChild.NodeType==XmlNodeType.CDATA));Check("archive metadata exact and no other payload",zip["metadata.bin"].SequenceEqual(File.ReadAllBytes(Path.Combine(s.Folder(1),"container.1")))&&zip["blobs/000.bin"].SequenceEqual(File.ReadAllBytes(s.Blob(1,0)))&&zip["blobs/001.bin"].SequenceEqual(File.ReadAllBytes(s.Blob(1,1))));
  string material=Path.Combine(root,"m");ProfileBackup.Materialize(verified,material);Check("materialize exact three selected leaves",Directory.GetFiles(material).Length==3&&verified.Files.All(f=>ProfileStore.Hash(File.ReadAllBytes(Path.Combine(material,f.PhysicalFileName)))==f.Sha256));Check("materialize does not touch source or archive",Fingerprint(s.Wgs)==before&&ProfileBackup.Verify(verified.FilePath).Sha256==verified.Sha256);string materialBefore=Fingerprint(material);Refuse("existing materialization destination refused",()=>ProfileBackup.Materialize(verified,material));Check("existing destination immutable",Fingerprint(material)==materialBefore);
  Refuse("backup destination inside source WGS refused",()=>ProfileBackup.Create(snapshot,selected,Path.Combine(s.Wgs,"backup")));Check("WGS destination refusal creates nothing",!Directory.Exists(Path.Combine(s.Wgs,"backup"))&&Fingerprint(s.Wgs)==before);Refuse("materialize inside source WGS refused",()=>ProfileBackup.Materialize(verified,Path.Combine(s.Wgs,"restore")));Refuse("materialize inside default WGS refused",()=>ProfileBackup.Materialize(verified,Path.Combine(ProfileBackupFixture.DefaultWgs,"restore")));
  var badDto=ProfileBackup.Verify(verified.FilePath);badDto.ProfileId=new string('a',64);Refuse("forged verified receipt refused",()=>ProfileBackup.Materialize(badDto,Path.Combine(root,"forged")));Check("forged receipt writes nothing",!Directory.Exists(Path.Combine(root,"forged")));
  foreach(string kind in new[]{"blob","metadata","xml","DTD","unknown-entry","traversal","manifest-unknown","manifest-duplicate","manifest-context","manifest-profile","manifest-guid","manifest-record","physical-traversal","file-sha","file-length","missing-entry"}){string path=Rewrite(verified.FilePath,"tamper-"+kind,data=>{
   if(kind=="blob")data["blobs/000.bin"][0]^=1;else if(kind=="metadata")data["metadata.bin"][0]^=1;else if(kind=="xml")data["selected-profile.xml"]=Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(data["selected-profile.xml"]).Replace("<![CDATA[", ""));else if(kind=="DTD")data["selected-profile.xml"]=Encoding.UTF8.GetBytes("<!DOCTYPE XbConnectedStorageSpace [<!ENTITY x SYSTEM 'file:///qa-only-do-not-open'>]>");else if(kind=="unknown-entry")data.Add("extra.bin",new byte[0]);else if(kind=="traversal"){data.Add("../metadata.bin",data["metadata.bin"]);data.Remove("metadata.bin");}else if(kind=="missing-entry")data.Remove("blobs/000.bin");else if(kind=="manifest-duplicate")data["manifest.json"]=Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(data["manifest.json"]).Replace("\"schema\":1", "\"schema\":1,\"schema\":1"));else{var m=Json(data["manifest.json"]);if(kind=="manifest-unknown")m["script"]="never execute";else if(kind=="manifest-context")m["contextToken"]=new string('a',64);else if(kind=="manifest-profile")m["profileId"]=new string('a',64);else if(kind=="manifest-guid")m["storageFolderGuid"]=Guid.NewGuid().ToString("N").ToUpperInvariant();else if(kind=="manifest-record")m["rawIndexRecordBase64"]=Convert.ToBase64String(new byte[10]);else{var fs=(System.Collections.IList)m["files"];var file=(Dictionary<string,object>)fs[1];if(kind=="physical-traversal")file["PhysicalFileName"]="..\\escape";else if(kind=="file-sha")file["Sha256"]=new string('a',64);else file["Bytes"]=(int)file["Bytes"]+1;}data["manifest.json"]=JsonBytes(m);}});Refuse("tampered archive refused "+kind,()=>ProfileBackup.Verify(path));}
  string big=Path.Combine(root,"big.zip");using(var fs=new FileStream(big,FileMode.CreateNew))fs.SetLength(ProfileBackup.MaximumArchiveBytes+1);Refuse("oversized archive refused before allocation",()=>ProfileBackup.Verify(big));
  string duplicate=Path.Combine(root,"dup.zip");using(var fs=new FileStream(duplicate,FileMode.CreateNew))using(var z=new ZipArchive(fs,ZipArchiveMode.Create)){foreach(var x in zip){string name=x.Key=="metadata.bin"?"blobs/000.bin":x.Key;var e=z.CreateEntry(name);using(var stream=e.Open())stream.Write(x.Value,0,x.Value.Length);}}Refuse("duplicate ZIP entry refused",()=>ProfileBackup.Verify(duplicate));
  var another=ProfileBackup.Create(snapshot,snapshot.Profiles.Single(p=>p.DisplayName=="1"),backups);Check("separate profile backups immutable and distinct",another.FilePath!=verified.FilePath&&another.ProfileId!=verified.ProfileId&&ProfileBackup.Verify(verified.FilePath).Sha256==verified.Sha256);
  var bytes=File.ReadAllBytes(s.Blob(2,0));bytes[0]^=1;File.WriteAllBytes(s.Blob(2,0),bytes);before=Fingerprint(s.Wgs);int backupCount=Directory.GetFiles(backups).Length;Refuse("unselected change invalidates selected backup",()=>ProfileBackup.Create(snapshot,selected,backups));Check("stale backup attempt has no new backup or store writes",Directory.GetFiles(backups).Length==backupCount&&Fingerprint(s.Wgs)==before);
  s=RichStore();string lower=Path.Combine(s.Wgs,Path.GetFileName(s.User).ToLowerInvariant());string temp=Path.Combine(s.Wgs,"temporary");Directory.Move(s.User,temp);Directory.Move(temp,lower);s.User=lower;snapshot=ProfileStore.Scan(s.Wgs);selected=snapshot.Profiles.Single(p=>p.DisplayName=="0");var lowerBackup=ProfileBackup.Create(snapshot,selected,backups);Check("accepted lowercase account path backs up",ProfileBackup.Verify(lowerBackup.FilePath).ContextToken==snapshot.ContextToken);
 }
